// How much of the intended text the voice agent has said, for the live caption.
// Written by a junior on the team; users report captions that go missing or look wrong.
export default function spokenPrefix(intended, spoken) {
  const n = intended.length;
  const m = spoken.length;
  // dp[i][j] is the length of the longest common subsequence of intended.slice(0, i) and spoken.slice(0, j).
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (intended[i - 1] === spoken[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
      else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }

  // Walk back from the last cell to rebuild the common subsequence: that is what the agent said.
  let i = n;
  let j = m;
  let said = '';
  while (i > 0 && j > 0) {
    if (intended[i - 1] === spoken[j - 1]) {
      said = intended[i - 1] + said;
      i -= 1;
      j -= 1;
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {
      i -= 1;
    } else {
      j -= 1;
    }
  }
  return said.trimEnd();
}
